/// 時刻(0〜23時)に応じたあいさつ。
public enum Greeting {
    public static func message(hour: Int) -> String {
        precondition((0...23).contains(hour))
        if hour < 12 { return "おはようございます" }
        if hour < 18 { return "こんにちは" }
        return "こんばんは"
    }
}

