import Testing
@testable import Greet

/// 境目: 5時は朝、4時は夜。
@Test func morningStartsAtFive() {
    #expect(Greeting.message(hour: 5) == "おはようございます")
    #expect(Greeting.message(hour: 4) == "こんばんは")
}

/// 境目: 11時は昼、10時は朝。
@Test func noonStartsAtEleven() {
    #expect(Greeting.message(hour: 11) == "こんにちは")
    #expect(Greeting.message(hour: 10) == "おはようございます")
}

